#include <stdio.h>
int main(void) {
    int a[4] = {10, 20, 30, 40};
    printf("%d\n", a[2]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[10];
    printf("%zu\n", sizeof(a));
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {3, 9, 4, 9, 1}, m = a[0];
    for (int i = 1; i < 5; i++)
        if (a[i] > m) m = a[i];
    printf("%d\n", m);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[3] = {1, 2, 3};
    int *p = a;
    printf("%d\n", p[1]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {1, 2, 3, 4, 5}, s = 0;
    for (int i = 0; i < 5; i++) s += a[i];
    printf("%d\n", s);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {1, 2, 3, 4, 5};
    for (int i = 0; i < 2; i++) {
        int t = a[i]; a[i] = a[4-i]; a[4-i] = t;
    }
    printf("%d %d %d %d %d\n", a[0], a[1], a[2], a[3], a[4]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {1, 2, 3, 4, 5};
    for (int i = 0; i <= 5; i++) printf("%d ", a[i]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {0, 10, 20, 30, 40};
    int *p = a + 3;
    printf("%d\n", p[-1] + *(p + 1));
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[6] = {10, 20, 30, 40, 50, 0};
    for (int i = 5; i > 2; i--) a[i] = a[i-1];
    a[2] = 99;
    printf("%d %d %d %d %d %d\n", a[0], a[1], a[2], a[3], a[4], a[5]);
    return 0;
}
